CREATE TABLE "RutasDespacho" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Codigo" character varying(20) NOT NULL,
    "Nombre" character varying(100) NOT NULL,
    "Zona" character varying(100) NOT NULL,
    "Origen" character varying(120) NOT NULL,
    "Destino" character varying(120) NOT NULL,
    "DistanciaKm" numeric(10,2) NOT NULL,
    "PeajeEstimado" numeric(18,2) NOT NULL,
    "Moneda" character varying(3) NOT NULL,
    "Activo" boolean NOT NULL DEFAULT true,
    "Observaciones" character varying(500),
    CONSTRAINT "PK_RutasDespacho" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_RutasDespacho_Textos" CHECK (
        length(btrim("Codigo")) > 0 AND length(btrim("Nombre")) > 0
        AND length(btrim("Zona")) > 0 AND length(btrim("Origen")) > 0
        AND length(btrim("Destino")) > 0),
    CONSTRAINT "CK_RutasDespacho_Distancia" CHECK ("DistanciaKm" > 0),
    CONSTRAINT "CK_RutasDespacho_Peaje" CHECK ("PeajeEstimado" >= 0),
    CONSTRAINT "CK_RutasDespacho_Moneda" CHECK ("Moneda" ~ '^[A-Z]{3}$')
);

CREATE UNIQUE INDEX "IX_RutasDespacho_CodigoNormalizado"
    ON "RutasDespacho" (lower(btrim("Codigo")));
CREATE INDEX "IX_RutasDespacho_Zona" ON "RutasDespacho" ("Zona");
